mapper.select:
SELECT notice_id, title, content, author, hit, write_date, category FROM notice
AND category = #{category, typeHandler=org.apache.ibatis.type.EnumTypeHandler}
AND title LIKE CONCAT('%', #{word}, '%')
AND author LIKE CONCAT('%', #{word}, '%')
AND (title LIKE CONCAT('%', #{word}, '%') OR author LIKE CONCAT('%', #{word}, '%'))
ORDER BY notice_id DESC LIMIT #{size} OFFSET #{offset}

SELECT notice_id, title, content, author, hit, write_date, category
FROM notice
WHERE notice_id = #{id}

mapper.update:
UPDATE notice
SET title = #{title}, content = #{content}, category = #{category, typeHandler=org.apache.ibatis.type.EnumTypeHandler}
WHERE notice_id = #{noticeId}

UPDATE notice
SET hit = hit + 1
WHERE notice_id = #{id}
